package com.backendSupermercado.supermercasdo.modules.reportes.compras.model;
public enum TipoReporteCompras { PEDIDOS("pedidos-general","Reporte general de pedidos"), PENDIENTES("pedidos-pendientes","Reporte de pedidos pendientes"), RECEPCIONES("recepciones-mercaderia","Reporte de recepciones de mercadería"), COMPARATIVO("comparativo-pedido-recibido","Reporte de productos pedidos y recibidos"), PROVEEDORES("compras-proveedor","Reporte de compras por proveedor"), PRODUCTOS("productos-comprados","Reporte de productos comprados"), RENTABILIDAD("rentabilidad-compras","Reporte de rentabilidad estimada"), DEVOLUCIONES("devoluciones-proveedor","Reporte de devoluciones a proveedores"), CUMPLIMIENTO("cumplimiento-proveedores","Reporte de cumplimiento de proveedores"), PERIODOS("compras-periodo","Reporte de compras por periodo"), ABASTECIMIENTO("abastecimiento-general","Reporte general de abastecimiento"); private final String ruta,titulo; TipoReporteCompras(String r,String t){ruta=r;titulo=t;} public String ruta(){return ruta;} public String titulo(){return titulo;} public static TipoReporteCompras desdeRuta(String r){for(var t:values())if(t.ruta.equalsIgnoreCase(r))return t;throw new IllegalArgumentException("Reporte de compras no válido");} }
